{{-- Tabela paginada de movimentações. Recebe $movimentacoes e $mensagemVazia --}}
<div class="table-wrap"><table><thead><tr><th>Data</th><th>Unidade</th><th>Item</th><th>Tipo</th><th>Quantidade</th><th>Observações</th></tr></thead><tbody>@forelse($movimentacoes as $m)<tr><td>{{ $m->movement_date->format('d/m/Y') }}</td><td>{{ $m->unit->name }}</td><td>{{ $m->item->sku }} · {{ $m->item->name }}</td><td><span class="badge {{ $m->type==='Entrada'?'ok':'low' }}">{{ $m->type }}</span></td><td>{{ $m->quantity }}</td><td>{{ $m->notes ?: '—' }}</td></tr>@empty<tr><td colspan="6" class="empty">{{ $mensagemVazia }}</td></tr>@endforelse</tbody></table></div>@if($movimentacoes->hasPages())<div class="pagination">@if($movimentacoes->onFirstPage())<span>‹</span>@else<a href="{{ $movimentacoes->previousPageUrl() }}">‹</a>@endif<span class="current">{{ $movimentacoes->currentPage() }}</span>@if($movimentacoes->hasMorePages())<a href="{{ $movimentacoes->nextPageUrl() }}">›</a>@endif</div>@endif
